void setup() {
  Serial.begin(115200);
  Serial.println("Enter two numbers separated by a comma (e.g., 25,15):");
}

void loop() {
  if (Serial.available() > 0) {
    // Read the first integer (stops reading at the comma)
    int num1 = Serial.parseInt();

    // Read the second integer (stops reading at the newline or buffer end)
    int num2 = Serial.parseInt();

    // Clear trailing characters (like \r or \n) from the buffer
    while (Serial.available() > 0) {
      Serial.read();
    }

    int sum = num1 + num2;

    // Display the result
    Serial.print("Sum: ");
    Serial.println(sum);
  }
}
